        private void FreezePlayerAndCamera(bool freeze)
        {
            var allInputs = FindObjectsByType<StarterAssets.StarterAssetsInputs>(FindObjectsSortMode.None);
            if (allInputs != null)
            {
                for (int i = 0; i < allInputs.Length; i++)
                {
                    if (allInputs[i] == null) continue;
                    if (freeze)
                    {
                        allInputs[i].move = Vector2.zero;
                        allInputs[i].look = Vector2.zero;
                        allInputs[i].jump = false;
                        allInputs[i].sprint = false;
                        allInputs[i].cursorInputForLook = false;
                        allInputs[i].cursorLocked = false;
                    }
                    else
                    {
                        allInputs[i].cursorInputForLook = true;
                        allInputs[i].cursorLocked = true;
                    }
                }
            }

            var allControllers = FindObjectsByType<StarterAssets.ThirdPersonController>(FindObjectsSortMode.None);
            if (allControllers != null)
            {
                for (int i = 0; i < allControllers.Length; i++)
                {
                    if (allControllers[i] == null) continue;
                    allControllers[i].LockCameraPosition = freeze;
                    allControllers[i].DisableMovement = freeze;
                }
            }
        }

