"using System.Collections;
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.UI;
using UnityEngine.SceneManagement;
using TMPro;

#if ENABLE_INPUT_SYSTEM
using UnityEngine.InputSystem;
#endif

namespace Wirabaya.UI
{
    /// <summary>
    /// Pengontrol Menu Settings & Pause Modern & Stabil:
    /// - Menata visual tombol, dropdown, dan slider dengan palet gelap elegan (Obsidian Slate Glass & Glowing Cyan).
    /// - Mencegah tabrakan visual: Menata spasi vertikal 90px antar baris pengaturan agar dropdown tidak menutupi slider.
    /// - Anti-Distorsi Skala: Mereset skala 1:1 pada controlsParent, audioParent, dan tombol tab agar teks tajam dan tidak gepeng.
    /// - Anti-Tabrakan HUD Gameplay: Otomatis menyembunyikan QuestUI (teks quest) dan StatsCanvas (darah/energi) saat pause, dan mengembalikannya saat resume.
    /// - Freeze Pemain & Kamera: Mengunci gerakan dan kamera pemain secara total selama menu pause terbuka.
    /// - Mengoperasikan langsung objek scene yang sudah ada tanpa instansiasi runtime yang memicu null reference.
    /// </summary>
    [RequireComponent(typeof(CanvasGroup))]
    public class SettingsMenuController : MonoBehaviour
    {
        public static SettingsMenuController Instance { get; private set; }
        public static float MouseSensitivity = 1f;

        [Header("=== KEY BINDING ===")]
        [Tooltip("Tombol keyboard alternatif untuk membuka/menutup menu.")]
        [SerializeField] private KeyCode toggleKey = KeyCode.Escape;

        [Header("=== HUD YANG DISEMBUNYIKAN SAAT PAUSE (ANTI-TABRAKAN) ===")]
        [Tooltip("Objek HUD gameplay (misal: 'NonDialogue') yang akan disembunyikan saat pause agar tidak bertabrakan dengan menu. Kosongkan untuk auto-detect.")]
        [SerializeField] private GameObject hudToHide;
        [Tooltip("Daftar objek tambahan yang ingin disembunyikan saat pause.")]
        [SerializeField] private GameObject[] additionalHudElementsToHide;

